+        receipts.set(id, { ...receipts.get(id), ...data });
+      },
+      findUnique: async ({ where }) => receipts.get(where.user_id_operation_id.operation_id)
+    }
+  };
+  // Model transaction rollback while using the real route and idempotency implementation.
